            v += 8
        # Prefer staying away from obstacles indirectly
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                if (x + dx, y + dy) in obstacles:
                    v -= 3
        # Slightly prefer moving toward center if nothing else
        v -= 0.2 * (abs(x - cx) + abs(y - cy))
        return v

    for dx, dy in moves:
        x, y = sx + dx, sy + dy
        if not (0 <= x < w and 0 <= y < h):
            continue
        if (x, y) in obstacles:
            continue
        v = score(x, y)
        if v > bestv:
            bestv = v
            best = [dx, dy]
    if best is None:
